  p_OperationKey_8e718883 := 'Workflow.Save';
  p_CategoryID_8e718883 := '0A7E9FD9-45BD-4ECF-ABD2-0EFF73C879E6';
  p_Description_8e718883 := 'Validate and persist a workflow — its graph of steps AND the triggers that fire it — by reconciling the substrates that already exist (a Flow agent for the graph, Scheduled Jobs for schedules). Creates no new storage: there is no Workflow table, because a second definition of a scheduled thing would give the scheduler two masters. Producer-agnostic — an agent over MCP, an Action, or the workflow editor all call this. Implemented by WorkflowSaveServerOperation in @memberjunction/task-graph.';
  p_InputTypeName_8e718883 := 'WorkflowSaveInput';
  p_InputTypeDefinition_8e718883 := '/** Input for `Workflow.Save`. */
export interface WorkflowSaveInput {
    /** The workflow to save, as a `WorkflowSpec`. */
    spec: {
        name: string;
        description?: string;
        status: ''Active'' | ''Paused'' | ''Draft'';
        graph: {
            workflowName: string;
            reasoning?: string;
            tasks: Array<{
                tempId: string;
                name: string;
                description: string;
                agentName?: string;
                assignToUser?: boolean;
                dependsOn: Array<string | { tempId: string; condition?: string; dependencyType?: ''Prerequisite'' | ''Corequisite'' | ''Optional'' }>;
                inputPayload?: Record<string, unknown>;
            }>;
            continuation?: ''message'' | ''reinvoke'' | ''none'';
            durable?: boolean;
        };
        triggers: Array<
            | { type: ''EntityEvent''; entityName: string; invocationType: string; filter?: string; scopeEntityName?: string; scopeRecordID?: string }
            | { type: ''Schedule''; cron: string; timezone?: string }
            | { type: ''OnDemand'' }>;
        notifications?: { condition: ''Always'' | ''OnFailure'' | ''OnChange''; recipients: string[] };
    };
}';
  p_InputTypeIsArray_8e718883 := FALSE;
  p_OutputTypeName_8e718883 := 'WorkflowSaveOutput';
  p_OutputTypeDefinition_8e718883 := '/** Output of `Workflow.Save`. */
export interface WorkflowSaveOutput {
    /** True when the workflow was validated and every substrate reconciled. */
    success: boolean;
    /** The Flow agent the workflow''s graph persisted as — the handle for everything downstream. */
    agentID?: string;
